arguments.command:
cat > /tmp/stackalloc_nint.cs << 'EOF'
Span<nint> a = stackalloc nint[4];
a[0] = 10;
a[1] = 20;
a[2] = nint.MaxValue;
a[3] = nint.MinValue;

Console.WriteLine($"Length: {a.Length}");
for (int i = 0; i < a.Length; i++)
    Console.WriteLine($"  a[{i}] = {a[i]}");

Span<nuint> b = stackalloc nuint[2];
b[0] = 42;
b[1] = nuint.MaxValue;

Console.WriteLine($"\nnuint Length: {b.Length}");
for (int i = 0; i < b.Length; i++)
    Console.WriteLine($"  b[{i}] = {b[i]}");

Console.WriteLine($"\nnint size: {sizeof(nint)} bytes");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");
EOF
